R=Path('D:/Codex/GRL研究');W=Path(__file__).parent;O=R/'outputs/grid215_cancellation_domain';S=R/'outputs/grid214_inner_head_generation';P=R/'outputs/grid213_inner_head_plan';REPO=R/'work/GRL-results-integration';A=REPO/'research_archive/power-grid-2026/protocols/GRID215_cancellation_domain'
def read(p):return json.loads(p.read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,v):(O/n).write_text(json.dumps(v,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf8',newline='\n')
def verify():
    for name in ['trained_freeze.json','scored_freeze.json','labelled_freeze.json']:
        for p,h in read(S/name).items():assert sha(S/p)==h,p
    assert read(S/'complete.json')['passed'] and read(S/'independent_audit.json')['passed']
    for p,h in read(O/'frozen_inputs.json').items():assert sha(R/p)==h,p

def main():
    assert not O.exists();O.mkdir();(O/'qualified_targets').mkdir()
    design=dict(stage='GRID215',scope='Saved GRID214 actual_STOP rows only; summarize allSTOP/base4CONT/cancelDisagreement. Freeze subsequent cancellation-only target without fitting/scoring a new policy.',primary_domain='actualSTOP and fixed inner depth4 CONT. Two-head disagreement not required. preSTOPCONT kept outside router training. No rescue or new CONT actions.',label='keep=actual_NET>0; actual_NET=original normalized next-batch gain minus original true fee. Current-label zero tie cancels in loss identity; default keep at predicted tie.',loss='structural_mass*abs(actual_NET)*1[predicted_keep != (actual_NET>0)], no class balance/clipping/oversampling/changed fee. This equals immediate signed regret against a one-batch keep/cancel label oracle, not full policy regret or week cost.',diagnostics='Per outer/seed and per date: rows/calls/profitable calls, positive and negative cost mass, top-call/date positive concentration, leave-one-date-out coverage only. No policy simulation or posthoc threshold selection.',future_inputs='Same public raw83+raw41=124; IDs/dates/innerfold/labels/realized gain excluded. Inner scores choose domain only; no inner p/mu predictors proposed to avoid their 8-date to12-date scale dependency. Base hidden features stay outer12-fit.',future_scope='At most12 same small classifiers, one per original outerfold/seed; a pool with no profitable support preserves baseline by an explicit KEEP constant and gets no learned cancellation. Hyperparameters/scale and exact files still require a training protocol before fitting.',dependency='Head-level crossgeneration only. Source baseNET and STOP selector fit outer12 including inner score dates. All ancestor dates must exclude own outer4; no pooling other outerfold data; no inner-held generalization claim because other inner heads depend on those dates.',fixed='Existing fees/controller/global128/64/stagnation2/.9/order/station/aliases/models unchanged. No fit, new model forward, new teacher/physical call, outer evaluation, final8, paper, FRAME comparison.')
