    files=[W/'run.py',O/'design.json',S/'bundles.json',S/'coverage_summary.json',S/'all_score_row_identities.json',S/'complete.json',S/'independent_audit.json',S/'delivery_receipt.json',P/'dependency_graph.json',R/'outputs/grid113_relational_learning/train_metadata.json']+[S/n for n in ['trained_freeze.json','scored_freeze.json','labelled_freeze.json']]+list((S/'labelled_samples').glob('*.npz'))
