        g=graph[b['bundle']];assert not set(g['all_ancestor_label_dates'])&set(b['outer_evaluation_dates']);z=np.load(S/'labelled_samples'/f"{b['bundle']}.npz");ids=z['meta_ids'].astype(int)
        assert np.allclose(z['actual_NET'],z['gain_normalized']-z['true_fee_normalized'],rtol=0,atol=1e-12)
