    decision=dict(use_base_continue_domain=True,do_not_require_depth4_depth5_disagreement=True,learn_keep_if_net_positive_with_abs_NET_cost=True,not_claim_new_objective_invention=True,keep_all_on_no_positive_support=lack,do_not_add_recovery_action_to_baseSTOP=True,retain_GRID208=True,training_started=False,next_training_needs_frozen_configs_inputs_and_pretraining_notice=True,no_inner_router_validation_claim=True)
    save('decision.json',decision)
